rows = []
current_module = None

def module(index):
    global current_module
    current_module = index

def add(slug, en_title, tr_title, en_teach, tr_teach, en_drill, tr_drill, en_check, tr_check, en_error, tr_error):
    if current_module is None:
        raise RuntimeError("Choose a module first")
    rows.append((current_module, slug, en_title, tr_title, en_teach, tr_teach,
                 en_drill, tr_drill, en_check, tr_check, en_error, tr_error))

